const rag = $('Armar ficha desde la base de conocimiento').first().json;
const kit = $('Traer kit de plantillas').first().json;

if (kit.truncated) {
  throw new Error('Notion devolvió el kit de plantillas truncado: revisar la página antes de generar');
}

const sinEmails = (s) =>
  String(s || '').replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, '[email omitido]');

return [{
  json: {
    cliente_id: rag.cliente_id,
    entradas_rag: rag.entradas,
    ficha: sinEmails(rag.ficha),
    propiedades: '',
    plantillas: sinEmails(kit.markdown),
  },
}];

const ORDEN = ['Propiedades','Servicio','Negocio','Equipo y contacto','Público','Objetivo','Tono','Restricción','Marca','Operación','Redes y línea base','Competencia','Producto','Arquetipo','FODA','Estrategia','Pilar','CTA','Ritmo','Decisión'];

const txt = (arr) => (Array.isArray(arr) ? arr.map((t) => t.plain_text || '').join('') : '');

const entradas = $input.all()
  .map((i) => {
    const p = i.json.properties || {};
    return {
      entrada: txt(p['Entrada'] && p['Entrada'].title),
      capa: (p['Capa'] && p['Capa'].select && p['Capa'].select.name) || '',
      categoria: (p['Categoría'] && p['Categoría'].select && p['Categoría'].select.name) || '',
      contenido: txt(p['Contenido'] && p['Contenido'].rich_text),
    };
  })
  .filter((e) => e.entrada && e.contenido);

if (entradas.length === 0) {
  throw new Error('La base de conocimiento no tiene entradas verificadas para este cliente');
}

const clienteId = $('When Executed by Another Workflow').first().json.cliente_id;

entradas.sort((a, b) => {
  const d = ORDEN.indexOf(a.categoria) - ORDEN.indexOf(b.categoria);
  return d !== 0 ? d : a.entrada.localeCompare(b.entrada, 'es');
});

const ficha = entradas
  .map((e) => `### ${e.entrada}\n[${e.capa} · ${e.categoria}]\n${e.contenido}`)
  .join('\n\n');

return [{ json: { cliente_id: clienteId, entradas: entradas.length, titulos: entradas.map((e) => e.entrada), ficha } }];
